func TestLoadPacks_ReadsMultipleFilesAndIgnoresOthers(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()

	// Two valid packs (yaml + json), one ignored (.txt), one malformed
	// (broken yaml — should be skipped, not fatal).
